<script setup lang="ts">
import ModalShell from '../../shared/ModalShell.vue';
import { inject, onBeforeUnmount, onMounted, ref, watch, type Ref } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import { api, displayTime, errorMessage, today, type Me, type WorkItem } from '@worktime/api-client';
import { reporting, type Capabilities, type Period, type ScopeInput } from '../../shared/reporting';
const me=inject<Ref<Me|undefined>>('me'),sharedBusy=inject<Ref<boolean>>('operationBusy'),busy=ref(false),error=ref(''),notice=ref(''),month=ref(today().slice(0,7)),period=ref<Period>(),caps=ref<Capabilities>();
const objects=ref<WorkItem[]>([]);
const modal=ref(''),reason=ref(''),requestId=ref(''),diff=ref<{fromVersionId:string;toVersionId:string|null;rows:Record<string,unknown>[]} >(),scope=ref<ScopeInput>(freshScope());
function freshScope():ScopeInput{return {userId:me?.value?.id??'',date:month.value+'-01',workItemId:null,objectType:'TIME',recordId:null,actions:['SAVE','SUBMIT','APPROVE'],reason:''};}
watch(busy,v=>{if(sharedBusy)sharedBusy.value=v;});
async function load(){busy.value=true;error.value='';diff.value=undefined;try{period.value=await reporting.period(month.value);}catch(e){period.value=undefined;error.value=errorMessage(e);}finally{busy.value=false;}}
function open(action:string,id=''){modal.value=action;reason.value='';requestId.value=id;scope.value=freshScope();error.value='';}
async function inspect(id:string){busy.value=true;error.value='';try{diff.value=id==='current'?await reporting.amendmentDiff(month.value,period.value!.activeAmendment!.id):await reporting.diff(month.value,id);}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function commit(){busy.value=true;error.value='';try{if(modal.value==='close')await reporting.close(month.value);else if(modal.value==='request')await reporting.request(month.value,reason.value,[{...scope.value,recordId:scope.value.recordId||null,reason:reason.value}]);else if(modal.value==='amend')await reporting.amend(month.value,reason.value,requestId.value||undefined);else if(modal.value==='scope')await reporting.scope(month.value,period.value!.activeAmendment!.id,{...scope.value,recordId:scope.value.recordId||null,reason:reason.value});else if(modal.value==='publish')await reporting.publish(month.value,period.value!.activeAmendment!.id,reason.value);modal.value='';notice.value='月份操作已由服务端确认。';await load();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
function objectChanged(){if(scope.value.objectType==='BASE'){scope.value.workItemId=null;scope.value.recordId=null;scope.value.actions=['BASE'];}else scope.value.actions=['SAVE','SUBMIT','APPROVE'];}
onMounted(async()=>{try{caps.value=await reporting.capabilities();objects.value=(await api.catalog()).workItems;await load();}catch(e){error.value=errorMessage(e);}});onBeforeRouteLeave(()=>!busy.value&&(!modal.value||!reason.value||window.confirm('申请说明尚未提交，确定离开？')));onBeforeUnmount(()=>{if(sharedBusy)sharedBusy.value=false;});
</script>
<template><div class="workflow-page"><div class="workflow-head"><div><h1>月报与修订</h1><p>封账保留当时事实。修改通过明确范围授权，旧正式版本始终可追溯。</p></div><form class="workflow-filters" @submit.prevent="load"><label>业务月份<input v-model="month" type="month" required :disabled="busy" /></label><button :disabled="busy">查询</button></form></div><p v-if="error" class="workflow-error" role="alert">{{ error }}</p><p v-if="notice" class="workflow-success">{{ notice }}</p><template v-if="period"><section class="workflow-panel"><div class="workflow-between"><h2>{{ period.month }} 月</h2><span class="workflow-tag" :data-state="period.status === 'AMENDING' ? 'AMENDING' : undefined">{{ ({OPEN:'开放填报',CLOSED:'已封账',AMENDING:'修订中'} as Record<string,string>)[period.status]??period.status }}</span></div><p>计划封账 {{ displayTime(period.scheduledCloseAt) }} · 实际封账 {{ displayTime(period.actualClosedAt) }}</p><div class="workflow-actions"><button v-if="period.canClose&&!period.latestVersionId" class="primary" :disabled="busy" @click="open('close')">执行到期封账</button><button v-if="period.latestVersionId" :disabled="busy" @click="open('request')">申请范围修订</button><button v-if="period.canUnlock&&period.latestVersionId&&!period.activeAmendment" :disabled="busy" @click="open('amend')">创建修订批次</button></div><p class="workflow-note">封账包含缺填、未决和已确认事实，不会自动将待审批记录转为通过。</p></section><section v-if="period.activeAmendment" class="workflow-panel"><div class="workflow-between"><h2>当前修订批次 {{ period.activeAmendment.id }}</h2><span>{{ period.activeAmendment.reason }}</span></div><p class="workflow-note">此批次发布前，正式报表仍使用上一发布版本。</p><div class="workflow-actions"><button v-if="period.canUnlock" :disabled="busy" @click="open('scope')">添加精确授权范围</button><button :disabled="busy" @click="inspect('current')">预览本次修订差异</button><button v-if="period.canPublish" class="primary" :disabled="busy||!diff||diff.toVersionId!==null" @click="open('publish')">发布新的正式版本</button></div><p v-if="!period.scopes.length">尚未授权任何记录。</p><article v-for="item in period.scopes" :key="item.id" class="workflow-readonly"><p>{{ item.date }} · 人员 {{ caps?.users.find(u=>u.id===item.userId)?.name??item.userId }} · {{ item.objectType==='BASE'?'人日基数':caps?.projects.find(w=>w.id===item.workItemId)?.name??item.workItemId }} · {{ item.recordId?`记录 ${item.recordId}`:'授权后新建范围' }}</p><p>动作 {{ item.actions.join('、') }} · {{ item.active?'有效':'已关闭' }} · {{ item.reason }}</p></article></section><section v-if="diff" class="workflow-panel"><h2>版本差异 · {{ diff.fromVersionId }} → {{ diff.toVersionId??'本次修订' }}</h2><p v-if="!diff.rows.length">所选范围没有差异。</p><details v-for="(row,i) in diff.rows" :key="i"><summary>{{ row.kind }} · 记录 {{ row.recordId }} · {{ row.change }}</summary><p>变更前</p><pre>{{ JSON.stringify(row.before,null,2) }}</pre><p>变更后</p><pre>{{ JSON.stringify(row.after,null,2) }}</pre></details></section><section class="workflow-panel"><h2>正式版本</h2><p v-if="!period.versions.length">本月尚未发布正式月报。</p><article v-for="version in period.versions" :key="version.id" class="version-row"><div><strong>V{{ version.versionNo }} · {{ version.month }}</strong><p>快照截止 {{ displayTime(version.cutoffAt) }} · 发布 {{ displayTime(version.publishedAt) }}</p><small>{{ version.reason }}</small></div><div class="workflow-actions"><RouterLink :to="`/reports/workload?version=${version.id}&month=${month}`">查看正式报表</RouterLink><button v-if="version.previousVersionId" :disabled="busy" @click="inspect(version.id)">比较上一版本</button></div></article></section><section class="workflow-panel"><h2>修订申请</h2><p v-if="!period.requests.length">暂无修订申请。</p><article v-for="item in period.requests" :key="item.id" class="version-row"><div><strong>申请 {{ item.id }} · {{ item.state }}</strong><p>{{ item.reason }}</p><p v-for="(s,i) in item.scopes" :key="i">{{ s.date }} · {{ s.objectType }} · {{ s.recordId?`记录 ${s.recordId}`:'新增记录' }} · {{ s.actions.join('、') }}</p></div><button v-if="period.canUnlock" :disabled="busy" @click="open('amend',item.id)">受理并建立修订批次</button></article></section></template><ModalShell v-if="modal" :busy="busy" @close="modal=''"><div class="workflow-overlay"><section class="workflow-dialog" role="dialog" aria-modal="true" aria-label="月份操作"><h2>{{ ({close:'执行封账',request:'申请范围修订',amend:'建立修订批次',scope:'添加精确授权',publish:'发布正式修订版'} as Record<string,string>)[modal] }}</h2><p v-if="modal==='publish'">发布将冻结整月新快照并关闭本批次授权。原正式版本保留。</p><form @submit.prevent="commit"><template v-if="['request','scope'].includes(modal)"><label>人员<select aria-label="人员" v-model="scope.userId" required :disabled="busy"><option v-for="u in caps?.users" :value="u.id" :key="u.id">{{ u.name }} / {{ u.employeeNo }}</option></select></label><label>日期<input v-model="scope.date" type="date" required :min="month+'-01'" :disabled="busy" /></label><label>记录类型<select aria-label="记录类型" v-model="scope.objectType" :disabled="busy" @change="objectChanged"><option value="TIME">工时</option><option value="ONSITE">现场日</option><option v-if="me?.canManage" value="BASE">人日基数</option></select></label><label v-if="scope.objectType!=='BASE'">归集对象<select aria-label="归集对象" v-model="scope.workItemId" required :disabled="busy"><option :value="null">选择对象</option><option v-for="w in objects" :key="w.id" :value="w.id">{{ w.name }}</option></select></label><label v-if="scope.objectType!=='BASE'">既有记录 ID<input v-model="scope.recordId" placeholder="留空仅授权之后新增记录" :disabled="busy" /></label><div v-if="scope.objectType!=='BASE'" class="workflow-actions"><label v-for="a in [{id:'ADD',name:'新增'},{id:'SAVE',name:'保存'},{id:'SUBMIT',name:'送审'},{id:'APPROVE',name:'通过'},{id:'REJECT',name:'驳回'},{id:'CORRECT',name:'更正'},{id:'DISPUTE',name:'争议'},{id:'TRANSFER',name:'转交审批'}]" :key="a.id"><input v-model="scope.actions" type="checkbox" :value="a.id" :disabled="busy" />{{ a.name }}</label></div></template><label>业务理由<textarea v-model="reason" rows="3" :required="modal!=='close'" maxlength="1000" :disabled="busy" /></label><p v-if="error" class="workflow-error">{{ error }}</p><div class="workflow-actions"><button type="button" :disabled="busy" @click="modal=''">取消</button><button class="primary" type="submit" :disabled="busy||(['request','scope'].includes(modal)&&!scope.actions.length)">{{ busy?'正在处理…':'确认提交' }}</button></div></form></section></div></ModalShell></div></template>
<style scoped>
.version-row { display: flex; align-items: center; justify-content: space-between; gap: var(--ts-space-16); padding: var(--ts-space-20) 0; border-bottom: 1px solid var(--ts-color-divider); }
.version-row > * { min-width: 0; overflow-wrap: anywhere; }
.workflow-readonly { margin-top: var(--ts-space-16); }
@media (max-width: 700px) { .version-row { display: block; } }
</style>
